document.addEventListener('DOMContentLoaded',()=>{const banner = document.getElementById('welcomeBanner');if(banner){const closeBtn = banner.querySelector('button');if(closeBtn)closeBtn.addEventListener('click',()=> banner.remove());}const revealElements = document.querySelectorAll('.reveal');function revealOnScroll(){const windowHeight = window.innerHeight;revealElements.forEach((el)=>{if(el.getBoundingClientRect().top < windowHeight - 100)el.classList.add('active');});}window.addEventListener('scroll',revealOnScroll);revealOnScroll();document.querySelectorAll('.counter').forEach((counter)=>{const updateCount =()=>{const target = +counter.getAttribute('data-target');const count = +counter.innerText;const increment = target / 200;if(count < target){counter.innerText = Math.ceil(count + increment);setTimeout(updateCount,15);}else{counter.innerText = target;}};updateCount();});document.querySelectorAll('.testimonial-read-more').forEach((button)=>{button.addEventListener('click',()=>{const card = button.closest('.testimonial-card');const isExpanded = card.classList.toggle('expanded');button.textContent = isExpanded ? 'Show Less' : 'Read More';});});const testimonialObserver = new IntersectionObserver((entries)=>{entries.forEach((entry)=>{if(entry.isIntersecting){entry.target.classList.add('in-view');testimonialObserver.unobserve(entry.target);}});},{threshold: 0.15});document.querySelectorAll('.testimonial-card').forEach((card)=> testimonialObserver.observe(card));});